/**
 * One schema per `type`; each requires its own field (`text`, `media`, `location`, `contact`, `contacts`, `poll` or `calendarEvent`). A body without `type` is sent as `text`. To a channel: `text`, `image`, `video` or `document`, with no `replyToMessageId`, `mentions` or `mentionAll`.
 */
export type SendMessageRequest =
  | SendTextMessageRequest
  | SendImageMessageRequest
  | SendVideoMessageRequest
  | SendAudioMessageRequest
  | SendVoiceMessageRequest
  | SendDocumentMessageRequest
  | SendStickerMessageRequest
  | SendLocationMessageRequest
  | SendContactMessageRequest
  | SendContactsMessageRequest
  | SendPollMessageRequest
  | SendCalendarEventMessageRequest;

export interface MessageEditRequest {
  /** The new text. */
  text: string;
}

export interface VoteRequest {
  /** Names of this poll's options. `[]` retracts the vote. */
  options: string[];
}

export interface ReactRequest {
  /** One emoji. An empty string removes the reaction. */
  emoji: string;
}

export interface LabelAssignRequest {
  labelId: string;
}

/** An image or video for a story, fetched by our servers. */
export interface StoryMedia {
  /**
   * Public `http(s)` URL our servers download (up to 5 redirects, 60 seconds, 100 MB), as `wuapi-media-fetcher/1.0 (+https://wuapi.dev)`. Private and internal addresses are refused; hosts with hotlink protection may refuse the download, which fails the message with a message naming the host and its answer (`fetch media from upload.wikimedia.org: HTTP 403`).
   */
  url: string;
  mimeType?: string;
}

/** A text story. */
export interface TextStoryCreateRequest {
  /** `text`. A body without `type` is also posted as text. */
  type?: "text";
  /** The story. Not blank; at most 4096 characters. */
  text: string;
  /** `#RRGGBB`. */
  backgroundColor?: string;
  /** WhatsApp's font. */
  font?: TextStoryCreateRequestFont;
}

export type TextStoryCreateRequestFont = 0 | 1 | 2 | 6 | 7 | 8 | 9 | 10;

/** An image or video story, with an optional caption. */
export interface MediaStoryCreateRequest {
  type: MediaStoryCreateRequestType;
  media: StoryMedia;
  /** Caption. At most 4096 characters. */
  text?: string;
}

export type MediaStoryCreateRequestType = "image" | "video";

/**
 * A text story (`type: text`, requires `text`) or a media story (`type: image` or `video`, requires `media`). A body without `type` is posted as `text`.
 */
export type StoryCreateRequest = TextStoryCreateRequest | MediaStoryCreateRequest;

export interface ChatPresenceRequest {
  /**
   * - `typing`: Show typing.
   * - `recording`: Show recording audio.
   * - `paused`: Clear the indicator.
   */
  state: ChatPresenceRequestState;
}

export type ChatPresenceRequestState = "typing" | "recording" | "paused";

export interface ReadReceiptsRequest {
  /**
   * wuapi ids of inbound messages in this chat. Default: every unread inbound message wuapi stores for the chat. At most 500.
   */
  messageIds?: string[];
}

/**
 * A chat of an account: a conversation with a contact, a group or a channel that wuapi holds at least one message of. Its name and latest message come from what wuapi stored; `unread`, `unreadCount`, `pinned`, `archived` and `muted` are WhatsApp's state of the chat, the one the chat actions change and `chat.updated` reports. wuapi learns that state from live changes (made through the API, on the phone or on another device), not from the sync after linking, so a state it has never observed is `null`, not `false`. The account's stories are not a chat.
 */
export interface Chat {
  /** Always `chat`. */
  object: "chat";
  /**
   * The chat id, as `chatId` on its messages: the contact id of a direct chat (`+584241112233` or `lid:<digits>`), the group id or the channel id.
   */
  id: string;
  /** The project of the chat's account. `null` when it is in none. */
  projectId: string | null;
  /** The account this belongs to. */
  accountId: string;
  type: ChatType;
  /**
   * The name to show: `savedName` when there is one, else the group's name or the contact's `profileName`. `null` when none is known yet.
   */
  name: string | null;
  /**
   * Direct chats: the name the account saved the contact under in its phone's address book, else the contact's business name. `null` when it has neither, and for groups and channels.
   */
  savedName: string | null;
  /**
   * Direct chats: the contact's WhatsApp profile name, as it came with their messages. `null` when unknown, and for groups and channels.
   */
  profileName: string | null;
  /** Direct chats: the contact's WhatsApp username (lowercase, without `@`), when WhatsApp shared one. */
  username: string | null;
  /**
   * The id of the chat's picture: the contact's profile picture, or the group's. It changes when the picture does, so a client can keep a downloaded picture until this differs, and ask `GET …/contacts/{contactId}/picture` (with this chat's id) only when it does. wuapi learns it from `contact.picture_updated`, from every picture read or set through the API and from contact lookups, never by asking WhatsApp while listing. `null` when unknown (never observed), when the chat has no picture or it is hidden from this account, and for channels (their picture is `pictureUrl` of the channel).
   */
  pictureId: string | null;
  /** The chat's latest message. `null` when it is no longer stored. */
  lastMessage: Message | null;
  /** When the latest message was sent or received. Lists are ordered by it, newest first. */
  lastMessageAt: string;
  /** The chat has unread messages or was marked as unread on WhatsApp. `null` when unknown. */
  unread: boolean | null;
  /**
   * Messages received and not read on WhatsApp yet: counted from the messages wuapi stored, and back to 0 when the account replies, sends read receipts, marks the chat as read or reads it on the phone. `0` with `unread: true` is a chat marked as unread. `null` when unknown: a chat that existed before wuapi kept this count or that only holds imported history, until it is read for the first time.
   */
  unreadCount: number | null;
  /** Pinned on WhatsApp. `null` when never observed. */
  pinned: boolean | null;
  /** Archived on WhatsApp. `null` when never observed. */
  archived: boolean | null;
  /** Muted on WhatsApp right now (a timed mute that ran out is `false`). `null` when never observed. */
  muted: boolean | null;
  /**
   * When the mute ends. `null` when the chat is not muted, is muted with no end, or its mute was never observed.
   */
  muteExpiresAt: string | null;
}

/** A page of `Chat` objects. */
export interface ChatList {
  /** Always `list`. */
  object: "list";
  items: Chat[];
  /** Pass as `cursor` to get the next page. `null` on the last page. */
  nextCursor: string | null;
}

