/**
 * Fired on real transitions: `account.qr_code_issued` when the account enters `qr_ready` (not on each QR rotation; poll the account for the current `qrCodeUrl`), `account.pairing_code_issued` when a new pairing code is issued, `account.disconnected` when the account loses its connection: at once when it does not recover on its own (`disconnectReason` `logged_out`, for example), or, for a drop the session reconnects from by itself, only if it is not `ready` again within a short reconnect grace (currently 20 seconds; `status` may then read `initializing` or `authenticating` while it keeps retrying), so a quick reconnect fires neither this nor `account.connected`; `account.connected` on `ready` (the first link, or back after `account.disconnected`), `account.failed` on `failed`. Deleting an account fires nothing.
 */
export interface AccountEvent {
  /** Event id (`evt_...`). Deduplicate on it. */
  id: string;
  object: "event";
  type: AccountEventType;
  createdAt: string;
  organizationId: string;
  /** The project the event belongs to, `null` when unassigned. */
  projectId: string | null;
  data: AccountEventData;
}

export type AccountEventType =
  | "account.qr_code_issued"
  | "account.pairing_code_issued"
  | "account.connected"
  | "account.disconnected"
  | "account.failed";

export interface AccountEventData {
  object: Account;
}

