/** The body of a webhook request, as returned by `verifyWebhook`. */
export type WebhookEvent =
  | (AccountEvent & { type: "account.qr_code_issued" })
  | (AccountEvent & { type: "account.pairing_code_issued" })
  | (AccountEvent & { type: "account.connected" })
  | (AccountEvent & { type: "account.disconnected" })
  | (AccountEvent & { type: "account.failed" })
  | (MessageEvent & { type: "message.received" })
  | (MessageEvent & { type: "message.sent" })
  | (MessageEvent & { type: "message.delivered" })
  | (MessageEvent & { type: "message.read" })
  | (MessageEvent & { type: "message.failed" })
  | (MessageEvent & { type: "message.deleted" })
  | (MessageEvent & { type: "message.media_downloaded" })
  | MessageEditedEvent
  | PollVotedEvent
  | GroupJoinedEvent
  | GroupUpdatedEvent
  | (GroupJoinRequestEvent & { type: "group.join_requested" })
  | (GroupJoinRequestEvent & { type: "group.join_request_revoked" })
  | ChatUpdatedEvent
  | ChatPresenceUpdatedEvent
  | ContactPresenceUpdatedEvent
  | ContactPictureUpdatedEvent
  | ContactUpdatedEvent
  | BlocklistUpdatedEvent
  | LabelUpdatedEvent
  | (CallEvent & { type: "call.received" })
  | (CallEvent & { type: "call.ended" })
  | (ChannelMessageEvent & { type: "channel.message_received" })
  | (ChannelMessageEvent & { type: "channel.message_updated" })
  | ChannelUpdatedEvent
  | HistorySyncedEvent
  | (ProjectEvent & { type: "project.created" })
  | (ProjectEvent & { type: "project.updated" })
  | (ProjectEvent & { type: "project.deleted" })
  | InvitationStatusChangedEvent
  | WebhookTestEvent;
